      two: "При двух классах softmax — это сигмоида разности: p₀ = σ(z₀ − z₁) = σ({d}) = {p}.",
      temp: "T = {t}: наибольшая вероятность {p}, у класса {label}.",
      temps: "Оценки делятся на температуру T перед softmax: низкая T заостряет вероятности к наибольшей оценке (вся вероятность при T → 0), высокая T сглаживает их к 1/{k} = {u} у каждого.",
      hard: "Перекрёстная энтропия с целью {label}{t}: L = −ln p = −ln {p} = {L}.",
      hardWhy: "Считается только вероятность цели: L = 0, когда она равна 1, и растёт без предела, когда она падает к 0.",
      confident: "Уверенная ошибка: {label} получил {p}, поэтому потеря велика, {L}. Перекрёстная энтропия наказывает уверенную ошибку гораздо сильнее неуверенной.",
      soft: "Перекрёстная энтропия с целевым распределением: L = −Σ yᵢ ln pᵢ = −({terms}) = {L}.",
      entropy: "Меньше всего она может быть равна энтропии самой цели H(y) = {H}, когда p = y; лишние {kl} — это KL-дивергенция от y к p.",
      uniform: "Равномерная догадка, 1/{k} каждому классу, стоила бы ln {k} = {u}.",
      gradient: "Градиент L по каждой оценке — просто {g}: оценка цели толкается вверх, а каждая другая вниз на свою вероятность.",
      classN: "класс {i}",
