      pieces: "A — сумма матриц ранга 1 σ₁u₁v₁ᵀ + σ₂u₂v₂ᵀ + …: каждая — столбец U, умноженный на соответствующую строку Vᵀ, с весом σ, начиная с наибольшей.",
      energy: "σ₁² + σ₂² + … = {total} — столько же, сколько сумма квадратов элементов A; на одно σ₁ приходится {share}.",
