      keepAll: "Если оставить {k}, получится в точности A, ведь ранг A равен {r}.",
      circle: "A переводит единичную окружность в эллипс: v₁ и v₂ переходят в σ₁u₁ и σ₂u₂ — его полуоси длиной {s1} и {s2}. Площадь эллипса — это площадь круга, умноженная на |det A| = σ₁σ₂ = {d}.",
      line: "σ₂ = 0, так что A сплющивает окружность в отрезок: направление v₂ теряется.",
