      cov: "Ковариационная матрица C = X̄ᵀX̄ / (m − 1) содержит на диагонали дисперсию каждого признака, а вне её — то, как два признака меняются вместе.",
      pcs: "Её собственные векторы, столбцы V, — главные компоненты: они перпендикулярны друг другу, первая — направление наибольшего разброса: {list}. Это правые сингулярные векторы X̄, а λᵢ = σᵢ² / (m − 1) — дисперсия вдоль каждой.",
